function validate([nums]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 1024) return 'nums needs 1 to 1024 values.';
  if ((nums.length & (nums.length - 1)) !== 0) return 'The length of nums must be a power of 2.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 1000000000)) return 'Each value is between 1 and 10^9.';
  return null;
}

