function minMaxGame(nums) {
  let current = nums;
  while (current.length > 1) {
    const next = new Array(current.length / 2);
    for (let i = 0; i < next.length; i++) {
      const first = current[2 * i];
      const second = current[2 * i + 1];
      next[i] = i % 2 === 0 ? Math.min(first, second) : Math.max(first, second);
    }
    current = next;
  }
  return current[0];
}

