function minMaxGame(nums) {
  // Top-down: the value at position index of some round comes from the two halves of its block of the original array.
  const solve = (lo, hi, index) => {
    if (hi - lo === 1) return nums[lo];
    const mid = (lo + hi) / 2;
    const a = solve(lo, mid, 2 * index);
    const b = solve(mid, hi, 2 * index + 1);
    return index % 2 === 0 ? Math.min(a, b) : Math.max(a, b);
  };
  return solve(0, nums.length, 0);
}

